SELECT X.didId, X.didNm, X.groupNm, COALESCE(X.schName, '없음') AS schName, X.didSttus, X.codeNm, X.RNUM FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.FRST_REGIST_PNTTM DESC) AS RNUM, TB.* FROM ( SELECT A.DID_ID AS didId, A.DID_NM AS didNm, B.GROUP_NM AS groupNm, ( SELECT C.SCH_NAME FROM TB_SCHEDULE C JOIN TB_GROUPDID G ON C.GROUP_CODE = G.GROUP_CODE JOIN TB_CONTENTSENDHISTORY F ON C.SCH_CODE = F.SCH_CODE WHERE TO_CHAR(NOW(), 'YYYYMMDD') BETWEEN C.SCH_STARTDAY AND C.SCH_ENDDAY AND C.GROUP_CODE = E.GROUP_CODE AND F.DID_ID = A.DID_ID
AND C.SCH_CODE = #{searchschCode}
AND F.DID_UPDATECHECK = 'Y' LIMIT 1 ) AS schName, A.DID_STTUS AS didSttus, A.DID_MAC AS didMac, FN_DETAILCODENM(A.DID_SWVER) AS codeNm FROM TB_DIDINFO A JOIN TB_GROUP B ON 1=1 JOIN TB_GROUPDID E ON A.DID_ID = E.DID_ID AND B.GROUP_CODE = E.GROUP_CODE WHERE 1=1
AND A.DID_SWVER = #{searchdidSwver}
AND A.GROUP_ID IN ( WITH RECURSIVE cte AS ( SELECT GROUP_ID, PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO WHERE GROUP_ID = #{groupId} UNION ALL SELECT g.GROUP_ID, g.PARENT_GROUP_ID FROM LETTNAUTHORGROUPINFO g JOIN cte ON g.PARENT_GROUP_ID = cte.GROUP_ID ) SELECT GROUP_ID FROM cte )
AND A.CENTER_ID = #{centerId}
) TB ) X WHERE X.RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

SELECT COALESCE(COUNT(*), 0)
FROM TB_DIDINFO A
JOIN TB_GROUP B ON 1=1
JOIN TB_GROUPDID E ON A.DID_ID = E.DID_ID AND B.GROUP_CODE = E.GROUP_CODE
WHERE 1=1

    AND A.DID_SWVER = #{searchdidSwver}



        AND A.DID_MODELTYPE = 'DIDRMODELTYPE03'


        AND A.ROLE_CODE IN
        (
        SELECT GROUP_ID
        FROM LETTNAUTHORGROUPINFO
        WHERE PARENT_GROUP_ID = #{groupCode}
        )


        AND A.ROLE_CODE = #{groupCode}



    AND A.CENTER_ID = #{centerId}


    AND A.DID_MODELTYPE = #{didModelType}

SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.FRST_REGIST_PNTTM DESC) AS RNUM, TB.* FROM ( SELECT A.DID_ID AS "didId", A.DID_NM AS "didNm", A.DID_IPADDR AS "didIpaddr", B.CENTER_NM AS "centerNm", CASE A.DID_STTUS WHEN 'N' THEN 'OFF' ELSE 'ON' END AS didSttus, A.DID_USEYN AS "didUseYn", FN_DETAILCODENM(A.DID_OS) AS DIDOS, A.DID_MAC AS DIDMAC,
( SELECT COUNT(*) FROM TB_SCHEDULE WHERE GROUP_CODE = ( SELECT GROUP_CODE FROM TB_GROUPDID WHERE DID_ID = A.DID_ID ) AND TO_CHAR(NOW(), 'YYYYMMDD') <= SCH_ENDDAY ) AS schCnt
FROM TB_DIDINFO A JOIN TB_CENTERINFO B ON A.CENTER_ID = B.CENTER_ID WHERE 1=1
AND A.DID_ID LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.DID_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.DID_MODELTYPE = 'DIDRMODELTYPE03'
AND A.ROLE_CODE IN ( SELECT GROUP_ID FROM LETTNAUTHORGROUPINFO WHERE PARENT_GROUP_ID = #{groupCode} )
AND A.ROLE_CODE = #{groupCode}
AND A.CENTER_ID = #{centerId}
AND A.DID_MODELTYPE = #{didModelType}
) TB ) TA WHERE TA.RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

SELECT A.DID_ID AS didId, A.DID_NM AS didNm, A.DID_MAC AS didMac, A.DID_IPADDR AS didIpaddr, FN_DETAILCODENM(A.DID_SWVER) AS didSwver, B.CENTER_NM AS centerNM, FN_DETAILCODENM(A.DID_TYPE) AS didType, FN_DETAILCODENM(A.DID_RESOLUTION) AS didResolution, DID_WIDTH AS didWidth, DID_HEIGHT AS didHeight, FN_DETAILCODENM(A.DID_IPTYPE) AS didIptype, FN_DETAILCODENM(A.DID_MODELTYPE) AS didModelType, DID_USEYN AS didUseYn, TO_CHAR(DID_ENDCONTIME, 'YYYY-MM-DD HH24:MI:SS') AS didEndContime, DID_ENDTIME AS didEndTime, DID_REMARK AS didRemark, C.GROUP_NM AS roleNm, DID_STTUS AS didSttus, FN_DETAILCODENM(A.DID_OS) AS didOs, FN_DETAILCODENM(A.DID_SERIALTYPE) AS didSerialtype, FN_DETAILCODENM(A.DID_SERIALPORT) AS didSerialport, FN_DETAILCODENM(A.DID_MONITERCNT) AS didMonitercnt, DID_STAETTIME AS didStartTime, DID_TIMEINTERVAL AS didTimeInterval, DID_SERIALJAVASCRIPT AS didSerialjavascript, ( SELECT E.GROUP_NM FROM TB_GROUPDID D JOIN TB_GROUP E ON D.GROUP_CODE = E.GROUP_CODE WHERE D.DID_ID = A.DID_ID ) AS groupNm, ( SELECT E.GROUP_CODE FROM TB_GROUPDID D JOIN TB_GROUP E ON D.GROUP_CODE = E.GROUP_CODE WHERE D.DID_ID = A.DID_ID ) AS groupCode,
( SELECT COUNT(*) FROM TB_SCHEDULE WHERE GROUP_CODE = ( SELECT GROUP_CODE FROM TB_GROUPDID WHERE DID_ID = A.DID_ID ) AND TO_CHAR(NOW(), 'YYYYMMDD') <= SCH_ENDDAY ) AS schCnt
FROM TB_DIDINFO A JOIN TB_CENTERINFO B ON A.CENTER_ID = B.CENTER_ID JOIN LETTNAUTHORGROUPINFO C ON A.ROLE_CODE = C.GROUP_ID WHERE A.DID_ID = #{didId}

SELECT COALESCE(DID_MAC, 'N')
FROM TB_DIDINFO
WHERE DID_ID = #{didId}

SELECT C.SCH_CODE AS schCode, C.SCH_NAME AS schNm, FN_DAYCONVERT(C.SCH_STARTDAY) AS schStartday, FN_DAYCONVERT(C.SCH_ENDDAY) AS schEndday, D.CON_SEQ AS conSeq, D.CON_NM AS conNm FROM TB_DIDINFO A JOIN TB_GROUPDID B ON A.DID_ID = B.DID_ID JOIN TB_SCHEDULE C ON B.GROUP_CODE = C.GROUP_CODE JOIN TB_CONTENTMUTIL D ON C.CONTENT_CODE = D.CON_SEQ WHERE A.DID_ID = #{didId}
AND TO_CHAR(NOW(), 'YYYYMMDD') <= C.SCH_ENDDAY
ORDER BY C.SCH_ENDDAY ASC

mapper.update:
UPDATE TB_DIDINFO SET
                      DID_MAC = #{didMac},
                      DID_IPADDR = #{didIpaddr},
                      DID_SENDINTERVAL = #{didSendInterval},
                      DID_TYPE = #{didType}
WHERE DID_ID = #{didId}

UPDATE TB_DIDINFO SET
                      DID_STTUS = #{didSttus},
                      DID_ENDCONTIME = NOW()
WHERE DID_ID = #{didId}
  AND TRIM(DID_MAC) = #{didMac}

UPDATE TB_DIDINFO SET
    DID_ENDTIME = #{didEndTime}
WHERE DID_ID = #{didId}
  AND TRIM(DID_MAC) = #{didMac}

mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.FRST_REGIST_PNTTM DESC) AS RNUM, TB.* FROM ( SELECT A.DID_ID AS "didId", A.DID_NM AS "didNm", A.DID_IPADDR AS "didIpaddr", B.CENTER_NM AS "centerNm", CASE A.DID_STTUS WHEN 'N' THEN 'OFF' ELSE 'ON' END AS didSttus, A.DID_USEYN AS "didUseYn", FN_DETAILCODENM(A.DID_OS) AS didOs, A.DID_MAC AS didMac, C.GROUP_NM AS roleNm,
( SELECT COUNT(*) FROM TB_SCHEDULE WHERE GROUP_CODE = ( SELECT GROUP_CODE FROM TB_GROUPDID WHERE DID_ID = A.DID_ID ) AND TO_CHAR(NOW(), 'YYYYMMDD') <= SCH_ENDDAY ) AS schCnt
FROM TB_DIDINFO A JOIN TB_CENTERINFO B ON A.CENTER_ID = B.CENTER_ID JOIN LETTNAUTHORGROUPINFO C ON A.ROLE_CODE = C.GROUP_ID WHERE 1=1
AND A.DID_ID LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.DID_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND ( A.ROLE_CODE IN (SELECT GROUP_ID FROM LETTNAUTHORGROUPINFO WHERE PARENT_GROUP_ID = #{groupCode}) OR A.ROLE_CODE = #{groupCode} )
AND A.DID_MODELTYPE IN ('DIDRMODELTYPE01', 'DIDRMODELTYPE02')
AND A.DID_MODELTYPE = 'DIDRMODELTYPE03'
AND A.CENTER_ID = #{centerId}
) TB ) TA WHERE TA.RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.FRST_REGIST_PNTTM DESC) AS RNUM, TB.* FROM ( SELECT A.DID_ID AS "didId", A.DID_NM AS "didNm", A.DID_IPADDR AS "didIpaddr", B.CENTER_NM AS "centerNm", CASE A.DID_STTUS WHEN 'N' THEN 'OFF' ELSE 'ON' END AS didSttus, A.DID_USEYN AS "didUseYn", FN_DETAILCODENM(A.DID_OS) AS didOs, A.DID_MAC AS didMac, DID_WIDTH AS didWidth, DID_HEIGHT AS didHeight, (SELECT e.GROUP_NM FROM TB_GROUPDID d JOIN TB_GROUP e ON d.group_code = e.GROUP_CODE WHERE d.DID_ID = a.DID_ID) AS groupNm, (SELECT e.GROUP_CODE FROM TB_GROUPDID d JOIN TB_GROUP e ON d.group_code = e.GROUP_CODE WHERE d.DID_ID = a.DID_ID) AS groupCode, ( SELECT COUNT(*) FROM TB_SCHEDULE
WHERE GROUP_CODE = (SELECT group_code FROM TB_GROUPDID WHERE did_id = a.did_id) AND TO_CHAR(NOW(), 'YYYYMMDD') <= SCH_ENDDAY
) AS schCnt FROM TB_DIDINFO A JOIN TB_CENTERINFO B ON A.CENTER_ID = B.CENTER_ID WHERE 1=1
AND A.CENTER_ID = #{centerId}
AND A.ROLE_CODE = #{groupCode}
) TB ) TA WHERE TA.RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}
